```cpp
struct Act { int s, e; };
bool cmp(Act a, Act b) { return a.e < b.e; }

int main() {
    Act acts[] = {{1,4},{3,5},{0,6},{5,7},{3,9}};
    int n = 5;
    sort(acts, acts+n, cmp);

    int cnt = 0, lastEnd = 0;
    for (int i = 0; i < n; i++) {
        if (acts[i].s >= lastEnd) {
            cnt++;
            lastEnd = acts[i].e;
        }
    }
    cout << cnt << endl;  // 3
}
```

